input.content:
#!/usr/bin/env python3
"""Static assertion for the CVE-2021-29650 candidate patch.

Runs with cwd = a clean target checkout with generated.patch applied.
Verifies the two intended barrier changes and that no other barrier changed.
Exits 0 when all assertions hold, 1 otherwise.
"""
import re
import sys
from pathlib import Path

errors = []


def read(path):
    return Path(path).read_text()


h = read("include/linux/netfilter/x_tables.h")
begin = re.search(r"xt_write_recseq_begin\(void\)\s*\{(.*?)\n\}", h, re.S)
if not begin:
    errors.append("xt_write_recseq_begin not found")
else:
    body = begin.group(1)
    if "__this_cpu_add(xt_recseq.sequence, addend);\n\tsmp_mb();" not in body:
        errors.append("xt_write_recseq_begin does not use smp_mb() after the sequence increment")
end = re.search(r"xt_write_recseq_end\(unsigned int addend\)\s*\{(.*?)\n\}", h, re.S)
if not end:
    errors.append("xt_write_recseq_end not found")
elif "smp_wmb();" not in end.group(1):
    errors.append("xt_write_recseq_end no longer uses smp_wmb() (unexpected change)")

c = read("net/netfilter/x_tables.c")
expected = ("smp_wmb();\n\ttable->private = newinfo;\n\n"
            "\t/* make sure all cpus see new ->private value */\n\tsmp_mb();")
if expected not in c:
    errors.append("xt_replace_table does not have smp_mb() immediately after table->private = newinfo "
                  "with the pre-assignment smp_wmb() retained")
if c.count("smp_wmb();") != 1:
    errors.append("net/netfilter/x_tables.c should retain exactly one smp_wmb() (pre-assignment): %d"
                  % c.count("smp_wmb();"))
if c.count("smp_mb();") != 1:
    errors.append("net/netfilter/x_tables.c should have exactly one smp_mb() (post-assignment): %d"
                  % c.count("smp_mb();"))

if errors:
    for e in errors:
        print("FAIL:", e)
    sys.exit(1)
print("OK: barrier assertions passed")

