                  "with the pre-assignment smp_wmb() retained")
if c.count("smp_wmb();") != 1:
    errors.append("net/netfilter/x_tables.c should retain exactly one smp_wmb() (pre-assignment): %d"
                  % c.count("smp_wmb();"))
if c.count("smp_mb();") != 1:
    errors.append("net/netfilter/x_tables.c should have exactly one smp_mb() (post-assignment): %d"
